<script setup>
import { computed, ref, watch } from 'vue'
import { useI18n } from 'vue-i18n'
import { newWeaponDesign, normalizeDesign, resizeSections, bladeGeometry, designPaths, designIssues, weaponStats, designRecipe, designRequirements, componentItems, METALS, SECTION_PROFILES, POINTS } from '../weapon-design'
import WeaponPreview from './WeaponPreview.vue'
import WeaponStats from './WeaponStats.vue'
const props = defineProps({ game: Object })
const emit = defineEmits(['command'])
const { t } = useI18n()
const draft = ref(normalizeDesign(props.game.workshop.activeDesign || props.game.workshop.design) || newWeaponDesign())
const selected = ref(0), graph = ref(null), dragging = ref(null), saved = ref(false)
const locked = computed(() => !!props.game.workshop.activeDesign || !!props.game.workshop.blade || !!props.game.workshop.mould || props.game.workshop.crucible.stage !== 'empty')
const geometry = computed(() => bladeGeometry(draft.value)), paths = computed(() => designPaths(draft.value))
const issues = computed(() => designIssues(draft.value)), recipe = computed(() => designRecipe(draft.value)), supplies = computed(() => designRequirements(props.game, draft.value)), stats = computed(() => weaponStats(draft.value))
const section = computed(() => draft.value.sections[selected.value] || draft.value.sections[0])
const viewBox = computed(() => { const l = draft.value.length; return `${-l * .12} ${-l * .65} ${l * 1.4} ${l * 1.3}` })
watch(draft, () => { saved.value = false }, { deep: true, flush: 'sync' })
function changeUnits(event) { resizeSections(draft.value, Number(event.target.value)); selected.value = Math.min(selected.value, draft.value.sections.length - 1); saved.value = false }
function move(event) {
  if (dragging.value === null || locked.value) return
  const pt = graph.value.createSVGPoint(); pt.x = event.clientX; pt.y = event.clientY
  const p = pt.matrixTransform(graph.value.getScreenCTM().inverse()), scale = geometry.value.controlScale
  const i = dragging.value
  draft.value.controls[i] = { x: Math.max([.12,.35,.4][i], Math.min([.6,.9,1.05][i], p.x / scale)), y: Math.max(-.55, Math.min(.55, -p.y / scale)) }
  saved.value = false
}
function begin(event, i) { if (locked.value) return; dragging.value = i; event.currentTarget.setPointerCapture(event.pointerId); move(event) }
function key(event, i) { if (!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(event.key) || locked.value) return; event.preventDefault(); const p = draft.value.controls[i]; p.x = Math.max([.12,.35,.4][i],Math.min([.6,.9,1.05][i],p.x + (event.key === 'ArrowLeft' ? -.015 : event.key === 'ArrowRight' ? .015 : 0))); p.y = Math.max(-.55,Math.min(.55,p.y + (event.key === 'ArrowDown' ? -.015 : event.key === 'ArrowUp' ? .015 : 0))); saved.value = false }
function save() { emit('command', 'saveDesign', { design: normalizeDesign(draft.value) }); saved.value = true }
</script>
<template><div class="weapon-designer"><p>{{ t('design.intro') }}</p><p v-if="locked" class="design-warning">{{ t('design.locked') }}</p><div class="designer-columns"><section><fieldset :disabled="locked"><label>{{ t('design.name') }}<input v-model="draft.name" maxlength="48"/></label><div class="design-fields"><label>{{ t('design.material') }}<select v-model="draft.material"><option v-for="(_, key) in METALS" :key="key" :value="key">{{ t('design.materials.' + key) }}</option></select></label><label>{{ t('design.ingots') }}<input type="number" min="1" max="12" :value="draft.ingots" @change="changeUnits"/></label><label>{{ t('design.length') }}<input v-model.number="draft.length" type="range" min="20" max="180"/>{{ draft.length }} cm</label><label>{{ t('design.point') }}<select v-model="draft.point"><option v-for="(_, key) in POINTS" :key="key" :value="key">{{ t('design.points.' + key) }}</option></select></label></div><label v-for="kind in ['handle','guard','pommel']" :key="kind">{{ t('design.' + kind) }}<select v-model="draft[kind]"><option v-for="item in componentItems(kind)" :key="item.id" :value="item.id">{{ t(item.nameKey) }} · {{ item.weightKg }} kg</option></select></label></fieldset><svg ref="graph" class="design-graph" :viewBox="viewBox" @pointermove="move" @pointerup="dragging = null" @pointercancel="dragging = null"><path :d="`M${-draft.length * .1} 0 H${draft.length * 1.2} M0 ${-draft.length * .6} V${draft.length * .6}`" stroke="#b5a271" stroke-width=".4"/><text :x="draft.length * 1.16" y="-3">X</text><text x="3" :y="-draft.length * .56">Y</text><path v-for="(path, i) in paths" :key="i" :d="path" :fill="i === selected ? '#e0bb75' : METALS[draft.material].color" stroke="#344c3f" stroke-width=".3" @click="selected = i"/><line v-for="(control, i) in draft.controls" :key="'line' + i" :x1="i ? draft.controls[i - 1].x * geometry.controlScale : 0" :y1="i ? -draft.controls[i - 1].y * geometry.controlScale : 0" :x2="control.x * geometry.controlScale" :y2="-control.y * geometry.controlScale" stroke="#dcb476" stroke-dasharray="2 2" stroke-width=".4"/><circle v-for="(control, i) in draft.controls" :key="i" :cx="control.x * geometry.controlScale" :cy="-control.y * geometry.controlScale" :r="draft.length * .026" fill="#873b43" stroke="#f4d08c" :stroke-width="draft.length * .004" tabindex="0" role="slider" :aria-label="t('design.control', { n: i + 1 })" :aria-valuenow="control.y" aria-valuemin="-0.55" aria-valuemax="0.55" @keydown="key($event, i)" @pointerdown.prevent="begin($event, i)"/></svg><small>{{ t('design.curveHelp') }}</small><WeaponPreview :design="draft" :highlight="selected"/></section><section><fieldset :disabled="locked"><label>{{ t('design.section') }}<select v-model.number="selected"><option v-for="(_, i) in draft.sections" :key="i" :value="i">{{ i + 1 }}</option></select></label><div class="design-fields"><label>{{ t('design.sectionLength') }}<input v-model.number="section.length" type="range" min="0.2" max="3" step="0.1"/>{{ section.length }}</label><label>{{ t('design.width') }}<input v-model.number="section.width" type="range" min="1" max="12" step="0.1"/>{{ section.width }} cm</label><label>{{ t('design.thickness') }}<input v-model.number="section.thickness" type="range" min="2" max="18" step="0.5"/>{{ section.thickness }} mm</label><label>{{ t('design.profile') }}<select v-model="section.profile"><option v-for="(_, key) in SECTION_PROFILES" :key="key" :value="key">{{ t('design.profiles.' + key) }}</option></select></label><label>{{ t('design.edge') }}<select v-model="section.edge"><option v-for="key in ['both','left','right','none']" :key="key" :value="key">{{ t('design.edges.' + key) }}</option></select></label></div></fieldset><WeaponStats :stats="stats"/><p>{{ t('design.volume', { used: geometry.volume.toFixed(0), available: recipe.volume.toFixed(0) }) }}</p><p>{{ t('design.recipe', { ore: recipe.oreCount, type: t('items.' + recipe.ore + '.name'), carbon: recipe.carbon, fuel: recipe.fuel, mass: recipe.blankMass.toFixed(2) }) }}</p><p v-for="issue in issues.errors" :key="issue" class="design-error">{{ t('design.issues.' + issue) }}</p><p v-for="issue in issues.warnings" :key="issue" class="design-warning">{{ t('design.issues.' + issue) }}</p><p v-for="entry in supplies.missing" :key="entry.itemId" class="design-warning">{{ t('design.missing', { n: entry.quantity, item: t('items.' + entry.itemId + '.name'), source: t('workshop.' + (entry.source === 'bag' ? 'bag' : 'source')) }) }}</p><p>{{ t('design.noRecovery') }}</p><button :disabled="locked || !!issues.errors.length" @click="save">{{ t('design.save') }}</button><span v-if="saved" role="status"> {{ t('design.saved') }}</span></section></div></div></template>
<style scoped>.weapon-designer{font-size:12px}.designer-columns{display:grid;grid-template-columns:1fr 1fr;gap:14px}.designer-columns>section{min-width:0}fieldset{border:0;padding:0;margin:0}.design-fields{display:grid;grid-template-columns:1fr 1fr;gap:8px}.weapon-designer label{display:flex;flex-direction:column;gap:4px;margin:6px 0;color:#d6c391}.weapon-designer input,.weapon-designer select{width:100%;box-sizing:border-box;background:#1d2c23;color:#eed6a3;border:1px solid #927a4f;padding:5px;border-radius:3px}.weapon-designer input[type=range]{padding:0;accent-color:#c7a363}.design-graph{width:100%;height:225px;background:#16281e;border:1px solid #ad9567;margin-top:10px;touch-action:none}.design-graph text{font-size:4px;fill:#dbbd80}.design-graph circle{cursor:grab;touch-action:none}.design-graph circle:focus{outline:none;fill:#db8b51}.design-error{color:#ffb1a7}.design-warning{color:#e2bc74}.weapon-designer button{background:#c4a363;color:#203627;border:1px solid #f0d49b;padding:8px 15px;border-radius:5px}.weapon-designer button:disabled{opacity:.4}@media(max-width:600px){.designer-columns{grid-template-columns:1fr}.design-graph{height:190px}}
</style>
